// 26-tap direct-form FIR, 8-bit samples, PIPELINED: products + delays in
// parallel, summed in the register -> short transient response.
module fir26_v8_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:25];
    wire [15:0] p1 = x * 8'd3;
    wire [15:0] p2 = xs[0] * 8'd23;
    wire [15:0] p3 = xs[1] * 8'd2;
    wire [15:0] p4 = xs[2] * 8'd52;
    wire [15:0] p5 = xs[3] * 8'd52;
    wire [15:0] p6 = xs[4] * 8'd61;
    wire [15:0] p7 = xs[5] * 8'd47;
    wire [15:0] p8 = xs[6] * 8'd33;
    wire [15:0] p9 = xs[7] * 8'd40;
    wire [15:0] p10 = xs[8] * 8'd63;
    wire [15:0] p11 = xs[9] * 8'd56;
    wire [15:0] p12 = xs[10] * 8'd44;
    wire [15:0] p13 = xs[11] * 8'd17;
    wire [15:0] p14 = xs[12] * 8'd43;
    wire [15:0] p15 = xs[13] * 8'd13;
    wire [15:0] p16 = xs[14] * 8'd18;
    wire [15:0] p17 = xs[15] * 8'd48;
    wire [15:0] p18 = xs[16] * 8'd28;
    wire [15:0] p19 = xs[17] * 8'd18;
    wire [15:0] p20 = xs[18] * 8'd23;
    wire [15:0] p21 = xs[19] * 8'd57;
    wire [15:0] p22 = xs[20] * 8'd21;
    wire [15:0] p23 = xs[21] * 8'd57;
    wire [15:0] p24 = xs[22] * 8'd24;
    wire [15:0] p25 = xs[23] * 8'd38;
    wire [15:0] p26 = xs[24] * 8'd25;
    wire [31:0] acc =  p1 + p2 + p3 + p4 + p5 + p6 + p7 + p8 + p9 + p10 + p11 + p12 + p13 + p14 + p15 + p16 + p17 + p18 + p19 + p20 + p21 + p22 + p23 + p24 + p25 + p26;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (int i = 0; i < 26; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (int i = 1; i < 26; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
